const input = $input.first().json;
const contractVersion = '1.0';
const testMode = input.testMode !== false;
const correlationId = typeof input.correlationId === 'string' && /^[A-Za-z0-9._:-]{1,128}$/.test(input.correlationId) ? input.correlationId : crypto.randomUUID();
const base = {contractVersion,testMode,correlationId};
const fail = (code,message) => [{json:{...base,ok:false,handled:false,recursionPrevented:false,error:{code,message}}}];
const allowed = new Set(['contractVersion','testMode','correlationId','workflowKey','error','recursionDepth','handledBy']);
if (Object.keys(input).some((key) => !allowed.has(key))) return fail('INVALID_REQUEST','Input contains unknown fields');
if (input.contractVersion !== undefined && input.contractVersion !== contractVersion) return fail('UNSUPPORTED_CONTRACT','contractVersion must be 1.0');
if (typeof input.workflowKey !== 'string' || !/^[A-Za-z0-9._:-]{2,128}$/.test(input.workflowKey)) return fail('INVALID_WORKFLOW','workflowKey is required');
const depth = input.recursionDepth ?? 0;
const handledBy = Array.isArray(input.handledBy) ? input.handledBy.filter((value) => typeof value === 'string').slice(0,5) : [];
if (!Number.isInteger(depth) || depth < 0) return fail('INVALID_RECURSION_DEPTH','recursionDepth must be a non-negative integer');
if (depth >= 1 || handledBy.includes('core-error-handler-v1')) return [{json:{...base,ok:true,handled:false,recursionPrevented:true,shouldEscalate:true,workflowKey:input.workflowKey,error:{code:'RECURSION_PREVENTED',message:'Shared error handler refused a recursive invocation',retryable:false}}}];
if (!input.error || typeof input.error !== 'object' || Array.isArray(input.error)) return fail('INVALID_ERROR','error object is required');
const code = typeof input.error.code === 'string' && /^[A-Z][A-Z0-9_]{1,63}$/.test(input.error.code) ? input.error.code : 'WORKFLOW_FAILED';
let message = typeof input.error.message === 'string' ? input.error.message : 'Workflow execution failed';
message = message.replace(/Bearer\s+[A-Za-z0-9._~+\/-]+/gi,'Bearer [REDACTED]').replace(/(api[_ -]?key|token|password|secret)\s*[:=]\s*[^\s,;]+/gi,'$1=[REDACTED]').slice(0,500);
const retryable = input.error.retryable === true;
const httpStatus = Number.isInteger(input.error.httpStatus) && input.error.httpStatus >= 100 && input.error.httpStatus <= 599 ? input.error.httpStatus : null;
const normalized = {code,message,retryable,httpStatus};
return [{json:{...base,ok:true,handled:true,recursionPrevented:false,shouldEscalate:!retryable,workflowKey:input.workflowKey,recursionDepth:1,handledBy:[...handledBy,'core-error-handler-v1'],error:normalized}}];
